        {
          "text": "Renamed the class StoryAreaPosition to AreaPosition, because it is now also used to describe the position of stickers on TON wallet cards.",
          "topic": "TON wallet",
          "refs": [
            "AreaPosition"
          ],
          "terms": []
        },
        {
          "text": "Added the classes ChatShareTheme, ChatShareThemeEmoji and ChatShareThemeUniqueGift, and the field share_theme to the class ChatFullInfo, describing the theme of the screen for sharing a link to a user or a chat.",
          "topic": "Chat share themes",
          "refs": [
            "ChatFullInfo",
            "ChatShareTheme",
            "ChatShareThemeEmoji",
            "ChatShareThemeUniqueGift"
          ],
          "terms": [
            "share_theme"
          ]
        },
        {
          "text": "Added the classes EmojiType, EmojiTypeEmoji and EmojiTypeCustomEmoji.",
          "topic": "Chat share themes",
          "refs": [
            "EmojiType",
            "EmojiTypeCustomEmoji",
            "EmojiTypeEmoji"
          ],
          "terms": []
        },
        {
          "text": "Added the classes ChatShareThemeBackdrop and ChatShareThemeBackdrops and the method getChatShareThemeBackdrops.",
          "topic": "Chat share themes",
          "refs": [
            "ChatShareThemeBackdrop",
            "ChatShareThemeBackdrops",
            "getChatShareThemeBackdrops"
          ],
          "terms": []
        },
        {
          "text": "Added the method getUniqueGift, allowing bots to get information about a unique gift by its name.",
          "topic": "Gifts",
          "refs": [
            "getUniqueGift"
          ],
          "terms": []
        },
        {
          "text": "Added the method deleteBusinessAccountGift, allowing bots to delete regular gifts owned by a managed business account without receiving Telegram Stars for them.",
          "topic": "Gifts",
          "refs": [
            "deleteBusinessAccountGift"
          ],
          "terms": []
        },
        {
          "text": "Allowed users with a Telegram Premium subscription to assign secondary usernames ending with “agent”, “ai”, “app”, “game”, or “gay” to up to 2 owned bots. Such usernames can be suggested in the field suggested_username of the class KeyboardButtonRequestManagedBot.",
          "topic": "General",
          "refs": [
            "KeyboardButtonRequestManagedBot"
          ],
          "terms": [
            "suggested_username"
          ]
        },
        {
          "text": "Added the class RichTextTonAddress representing an address in the TON blockchain in a RichMessage.",
          "topic": "General",
          "refs": [
            "RichMessage",
            "RichTextTonAddress"
          ],
          "terms": []
        },
        {
          "text": "Added the type “ton_address” to the class MessageEntity for addresses in the TON blockchain.",
          "topic": "General",
          "refs": [
            "MessageEntity"
          ],
          "terms": []
        },
        {
          "text": "Added the type “bank_card_number” to the class MessageEntity for bank card numbers.",
          "topic": "General",
          "refs": [
            "MessageEntity"
          ],
          "terms": []
        },
        {
          "text": "Added the parameters custom_description_parse_mode and custom_description_entities to the methods verifyUser and verifyChat.",
          "topic": "General",
          "refs": [
            "verifyChat",
            "verifyUser"
          ],
          "terms": [
            "custom_description_entities",
            "custom_description_parse_mode"
          ]
        },
        {
          "text": "Added the class PaidMessagesWaived and the field paid_messages_waived to the class Message for service messages about the sender using a link which allows sending messages without paying Telegram Stars.",
          "topic": "General",
          "refs": [
            "Message",
            "PaidMessagesWaived"
          ],
          "terms": [
            "paid_messages_waived"
          ]
        },
        {
          "text": "Added the ability to create links to topics in private chats with the bot in the format `https://t.me/<bot_username>/<message_thread_id>`. Such a link opens the topic only for the user in the private chat with whom the topic exists.",
          "topic": "General",
          "refs": [],
          "terms": []
        }
      ]
    },
